def pick_object(obj_name):
    """Precondition: Gripper is empty and obj_name is visible; Postcondition: obj_name is grasped in gripper."""
    cands = grasp_candidates(obj_name)
    cands = sorted(cands, key=lambda c: c.get("score", 0), reverse=True)
    for cand in cands:
        res = grasp(cand)
        if res.get("holding_something", False):
            return True
    return False

def pick_thin_object(obj_name, min_grasp_height=0.025):
    """Gripper is empty; grasps the object above min_grasp_height to avoid table collision, ending with object held."""
    cands = grasp_candidates(obj_name)
    valid_cands = [c for c in cands if c.get("fits_open_fingers", True)]
    valid_cands.sort(key=lambda c: c.get("score", 0), reverse=True)

    for cand in valid_cands:
        cand_copy = dict(cand)
        if cand_copy.get("height", 0) < min_grasp_height:
            cand_copy["height"] = min_grasp_height
        res = grasp(cand_copy)
        if res.get("holding_something", False):
            return True

    if valid_cands:
        cand_copy = dict(valid_cands[0])
        if cand_copy.get("height", 0) < min_grasp_height:
            cand_copy["height"] = min_grasp_height
        res = grasp(cand_copy)
        return res.get("holding_something", False)
    return False

def pick_object_v2(obj_name):
    """Pre: gripper is empty and obj_name is visible. Post: robot is holding obj_name if a grasp candidate succeeded."""
    cands = grasp_candidates(obj_name)
    cands = sorted(cands, key=lambda c: c.get("score", 0), reverse=True)
    for cand in cands:
        res = grasp(cand)
        if res.get("holding_something", False):
            return True
    return False

def pick_object_with_candidates(obj_name, preferred_source="contact-graspnet"):
    """Picks an object by evaluating grasp candidates, returning True if successfully grasped."""
    cands = grasp_candidates(obj_name)
    if not cands:
        return False

    filtered_cands = [
        c for c in cands
        if (preferred_source is None or c.get("source") == preferred_source)
        and c.get("fits_open_fingers", True)
    ]
    if not filtered_cands:
        filtered_cands = [c for c in cands if c.get("fits_open_fingers", True)] or cands

    sorted_cands = sorted(filtered_cands, key=lambda c: c.get("score", 0), reverse=True)

    for cand in sorted_cands:
        res = grasp(cand)
        if res.get("holding_something", False):
            return True
    return False

def drop_into_container_v2(obj_name, zone_name, safe_z_offset=0.15):
    """Assumes object is held above container; releases object to fall upright inside and retreats gripper."""
    open_gripper()
    retreat(dz=safe_z_offset)
    go_home()
    return check(obj_name, zone_name)

def pick_filtered_grasp(obj_name):
    """Picks an object by filtering and sorting candidate grasps by clearance, tilt, and score; returns True if grasped."""
    candidates = grasp_candidates(obj_name)
    valid = [
        c
        for c in candidates
        if c.get("fits_open_fingers", True)
        and c.get("hand_clear", True)
        and c.get("fingers_clear", True)
    ]
    if not valid:
        return False

    valid.sort(key=lambda c: (c.get("tilt_deg", 0), -c.get("score", 0)))
    for chosen in valid:
        res = grasp(chosen)
        if res.get("holding_something", False):
            return True
    return False

def choose_and_execute_grasp(obj_name):
    """Precondition: Gripper is empty and obj_name exists; Postcondition: Object is grasped using the best valid candidate."""
    candidates = grasp_candidates(obj_name)
    valid_cands = [c for c in candidates if c.get("fits_open_fingers", True)]
    if not valid_cands:
        valid_cands = candidates
    clear_cands = [
        c for c in valid_cands
        if c.get("hand_clear", True) and c.get("fingers_clear", True)
    ]
    chosen = clear_cands[0] if clear_cands else (valid_cands[0] if valid_cands else None)
    if chosen is None:
        raise RuntimeError(f"No viable grasp candidate found for {obj_name}")
    grasp(chosen)

def choose_filtered_grasp(obj_name):
    """Precondition: Gripper is empty and obj_name is reachable; Postcondition: Object is grasped using best clear candidate, or False if failed."""
    cands = grasp_candidates(obj_name)
    if not cands:
        return False
    # Filter clear candidates, preferring valid fit
    clear_cands = [c for c in cands if c.get("hand_clear", True) and c.get("fingers_clear", True) and c.get("fits_open_fingers", True)]
    if not clear_cands:
        clear_cands = [c for c in cands if c.get("fits_open_fingers", True)]
    if not clear_cands:
        clear_cands = cands
    chosen = max(clear_cands, key=lambda c: c.get("score", 0))
    res = grasp(chosen)
    return res.get("holding_something", False)
